class Solution {
public:
    int matrixSum(std::vector<std::vector<int>>& nums) {
        for (auto& row : nums) {
            std::sort(row.begin(), row.end());
        }
        int m = nums.size(), n = nums[0].size();
        int score = 0;
        for (int c = 0; c < n; c++) {
            int max_val = 0;
            for (int r = 0; r < m; r++) {
                max_val = std::max(max_val, nums[r][c]);
            }
            score += max_val;
        }
        return score;
    }
};

class Solution {
    public int matrixSum(int[][] nums) {
        for (int[] row : nums) {
            Arrays.sort(row);
        }
        int m = nums.length, n = nums[0].length;
        int score = 0;
        for (int c = 0; c < n; c++) {
            int maxVal = 0;
            for (int r = 0; r < m; r++) {
                maxVal = Math.max(maxVal, nums[r][c]);
            }
            score += maxVal;
        }
        return score;
    }
}

var matrixSum = function(nums) {
    for (const row of nums) {
        row.sort((a, b) => a - b);
    }
    const m = nums.length, n = nums[0].length;
    let score = 0;
    for (let c = 0; c < n; c++) {
        let maxVal = 0;
        for (let r = 0; r < m; r++) {
            maxVal = Math.max(maxVal, nums[r][c]);
        }
        score += maxVal;
    }
    return score;
};
